PRAGMA foreign_keys = ON;
CREATE TABLE kunden (KundenID INTEGER PRIMARY KEY, Name TEXT NOT NULL, Stadt TEXT NOT NULL, Land TEXT NOT NULL, Kundentyp TEXT NOT NULL);
CREATE TABLE orte (OrtID INTEGER PRIMARY KEY, Bezeichnung TEXT NOT NULL, Stadt TEXT NOT NULL, Kapazitaet INTEGER NOT NULL);
CREATE TABLE veranstaltungen (EventID INTEGER PRIMARY KEY, Titel TEXT NOT NULL, Kategorie TEXT NOT NULL, Preis REAL NOT NULL, OrtID INTEGER NOT NULL, Datum TEXT NOT NULL, Status TEXT NOT NULL, FOREIGN KEY (OrtID) REFERENCES orte(OrtID));
CREATE TABLE mitarbeitende (MitarbeiterID INTEGER PRIMARY KEY, Vorname TEXT NOT NULL, Nachname TEXT NOT NULL, Bereich TEXT NOT NULL, Aktiv INTEGER NOT NULL);
CREATE TABLE buchungen (BuchungID INTEGER PRIMARY KEY, KundenID INTEGER NOT NULL, EventID INTEGER NOT NULL, AnzahlTickets INTEGER NOT NULL, Buchungsdatum TEXT NOT NULL, Status TEXT NOT NULL, FOREIGN KEY (KundenID) REFERENCES kunden(KundenID), FOREIGN KEY (EventID) REFERENCES veranstaltungen(EventID));
CREATE TABLE einsaetze (EinsatzID INTEGER PRIMARY KEY, EventID INTEGER NOT NULL, MitarbeiterID INTEGER NOT NULL, Stunden REAL NOT NULL, Rolle TEXT NOT NULL, FOREIGN KEY (EventID) REFERENCES veranstaltungen(EventID), FOREIGN KEY (MitarbeiterID) REFERENCES mitarbeitende(MitarbeiterID));
